// Extract subscription data from webhook body
const body = $input.first().json.body;

return [{
  json: {
    email: body.email,
    specific_bills: body.specific_bills || [],
    welcome_alerts: body.welcome_alerts || [],
    keywords: body.keywords || [],
    ministries: body.ministries || [],
    email_frequency: body.email_frequency || 'instant',
    subscription_id: body.subscription_id || body.id
  }
}];

const data = $input.first().json;

// Format keywords for display
const keywordsDisplay = data.keywords.length > 0 
  ? data.keywords.join(', ') 
  : 'None specified';

// Format ministries for display
const ministriesDisplay = data.ministries.length > 0 
  ? data.ministries.join(', ') 
  : 'All ministries';

// Format specific bills for display
const specificBillsDisplay = data.specific_bills && data.specific_bills.length > 0 
  ? data.specific_bills.join(', ') 
  : 'None specified';

// Format frequency for display
const frequencyDisplay = {
  'instant': 'Instant (as bills are introduced)',
  'daily': 'Daily Digest (once per day at 8 AM)',
  'weekly': 'Weekly Digest (once per week)'
}[data.email_frequency] || data.email_frequency;

// Dynamic HTML for AI Summaries
let alertsHtml = '';
if (data.welcome_alerts && data.welcome_alerts.length > 0) {
  alertsHtml = `
    <div style="background: #f0fdf4; padding: 25px; border-left: 5px solid #22c55e; margin: 30px 0; border-radius: 8px;">
      <h3 style="color: #166534; margin-top: 0; font-size: 20px;">⚡ Immediate AI Bill Summaries</h3>
      <p style="color: #15803d; margin-bottom: 20px;">You requested immediate alerts for specific bills. Our LoRA AI has generated these summaries for you:</p>
  `;
  for (const alert of data.welcome_alerts) {
    alertsHtml += `
      <div style="margin-top: 20px; padding-top: 20px; border-top: 1px solid #bbf7d0;">
        <h4 style="margin: 0 0 12px 0; color: #14532d; font-size: 18px;">📜 ${alert.bill_title} (ID: ${alert.bill_id})</h4>
        <div style="background: white; padding: 15px; border-radius: 6px; border: 1px solid #dcfce7; color: #333; line-height: 1.6;">${alert.summary.replace(/\n/g, '<br>')}</div>
        <a href="http://localhost:5173/explore?q=${encodeURIComponent(alert.bill_title)}" style="display: inline-block; margin-top: 15px; background: #22c55e; color: white; padding: 8px 16px; border-radius: 4px; text-decoration: none; font-weight: bold;">View Full Bill Details →</a>
      </div>
    `;
  }
  alertsHtml += `</div>`;
}

return [{
  json: {
    email: data.email,
    keywordsDisplay: keywordsDisplay,
    ministriesDisplay: ministriesDisplay,
    specificBillsDisplay: specificBillsDisplay,
    frequencyDisplay: frequencyDisplay,
    alertsHtml: alertsHtml
  }
}];
